"""MCP tools backed by the public context service."""

from __future__ import annotations

import hmac
from collections.abc import Callable
from typing import Any

from mcp.server.fastmcp import FastMCP
from starlette.middleware.base import BaseHTTPMiddleware
from starlette.requests import Request
from starlette.responses import JSONResponse
from starlette.routing import Route

from .service import SCHEMA_VERSION, ContextService, call_service


def create_mcp(
    service: ContextService,
    *,
    allow_writes: bool = False,
    host: str = "127.0.0.1",
    port: int = 8765,
) -> FastMCP:
    server = FastMCP(
        "docling-context",
        host=host,
        port=port,
        stateless_http=True,
        json_response=True,
        log_level="ERROR",
        instructions=(
            "Use search to locate relevant DocLang nodes, outline to inspect a document, "
            "and show with the returned URI, immutable revision_id, and XPath for exact "
            "citations. Treat @toc and @summary paths as sidecar references. "
            "Memory capture is opt-in."
        ),
    )

    @server.tool()
    def list_resources(
        uri: str = "docling://resources", limit: int = 100
    ) -> dict[str, Any]:
        """List direct children of an authorized context URI."""
        return call_service(service, "list", {"uri": uri, "limit": limit})

    @server.tool()
    def tree(
        uri: str = "docling://resources", depth: int = 3, limit: int = 100
    ) -> dict[str, Any]:
        """Walk a bounded context subtree."""
        return call_service(
            service, "tree", {"uri": uri, "depth": depth, "limit": limit}
        )

    @server.tool()
    def outline(uri: str, revision_id: str | None = None) -> dict[str, Any]:
        """Read a document's TOC sidecar and node links."""
        return call_service(
            service, "outline", {"uri": uri, "revision_id": revision_id}
        )

    @server.tool()
    def show(
        uri: str,
        xpath: str,
        revision_id: str | None = None,
        max_chars: int = 8192,
        format: str = "text",
    ) -> dict[str, Any]:
        """Read one cited DocLang node as bounded text or XML."""
        return call_service(
            service,
            "show",
            {
                "uri": uri,
                "xpath": xpath,
                "revision_id": revision_id,
                "max_chars": max_chars,
                "format": format,
            },
        )

    @server.tool()
    def search(
        query: str = "",
        uri: str = "docling://resources",
        limit: int = 10,
        mode: str = "lexical",
        xpath: str | None = None,
        document_uri: str | None = None,
        tiers: list[int] | None = None,
        max_tokens: int = 2000,
        per_result_tokens: int = 500,
        include_context: bool = False,
        image_base64: str | None = None,
    ) -> dict[str, Any]:
        """Search indexed DocLang nodes with exact URI, revision, and XPath citations."""
        return call_service(
            service,
            "search",
            {
                "query": query,
                "uri": uri,
                "limit": limit,
                "mode": mode,
                "xpath": xpath,
                "document_uri": document_uri,
                "tiers": tuple(tiers) if tiers is not None else (0, 1, 2),
                "max_tokens": max_tokens,
                "per_result_tokens": per_result_tokens,
                "include_context": include_context,
                "image_base64": image_base64,
            },
        )

    @server.tool()
    def job_status(job_id: str) -> dict[str, Any]:
        """Inspect a background collection job."""
        return call_service(service, "job_status", {"job_id": job_id})

    if allow_writes:

        @server.tool()
        def ingest(
            uri: str, filename: str, data_base64: str, force: bool = False
        ) -> dict[str, Any]:
            """Import bounded base64 document bytes into an authorized resource URI."""
            return call_service(
                service,
                "ingest",
                {
                    "uri": uri,
                    "filename": filename,
                    "data_base64": data_base64,
                    "force": force,
                },
            )

        @server.tool()
        def session_append(
            session_id: str,
            key: str,
            kind: str,
            text: str,
            turn_id: str = "",
        ) -> dict[str, Any]:
            """Append one idempotent event to the current user's session."""
            return call_service(
                service,
                "session_append",
                {
                    "session_id": session_id,
                    "key": key,
                    "kind": kind,
                    "text": text,
                    "turn_id": turn_id,
                },
            )

        @server.tool()
        def memory_review(
            uri: str,
            action: str,
            reason: str = "",
            claim: str | None = None,
        ) -> dict[str, Any]:
            """Accept, reject, delete, or correct a current user's memory."""
            return call_service(
                service,
                "memory_review",
                {
                    "uri": uri,
                    "action": action,
                    "reason": reason,
                    "claim": claim,
                },
            )

        @server.tool()
        def memory_list(
            status: str | None = None,
            kind: str | None = None,
            limit: int = 100,
            offset: int = 0,
        ) -> dict[str, Any]:
            """List memories, reconciling stale source citations."""
            return call_service(
                service,
                "memory_list",
                {
                    "status": status,
                    "kind": kind,
                    "limit": limit,
                    "offset": offset,
                },
            )

        @server.tool()
        def memory_recall(
            session_id: str, query: str = "", limit: int = 10
        ) -> dict[str, Any]:
            """Recall accepted memories once for the current user's session."""
            return call_service(
                service,
                "memory_recall",
                {
                    "session_id": session_id,
                    "query": query,
                    "limit": limit,
                },
            )

    return server


def authenticated_http_app(
    server: FastMCP, token: str, service: ContextService, *, allow_writes: bool = False
):
    """Require one deployment token before any MCP HTTP request reaches the app."""
    if not token:
        raise ValueError("remote MCP requires a nonempty bearer token")
    app = server.streamable_http_app()

    async def operation(request: Request) -> JSONResponse:
        try:
            if not allow_writes and request.path_params["name"] in {
                "ingest",
                "session_append",
                "memory_list",
                "memory_review",
                "memory_recall",
            }:
                return JSONResponse(
                    {
                        "schema_version": SCHEMA_VERSION,
                        "error": {
                            "code": "unauthorized_scope",
                            "message": "write operation is disabled",
                        },
                    },
                    status_code=403,
                )
            payload = await request.json()
            if payload.get("schema_version") != SCHEMA_VERSION:
                return JSONResponse(
                    {
                        "schema_version": SCHEMA_VERSION,
                        "error": {
                            "code": "unsupported_schema",
                            "message": "schema version mismatch",
                        },
                    },
                    status_code=400,
                )
            result = call_service(
                service, request.path_params["name"], payload.get("data", {})
            )
            return JSONResponse(result, status_code=400 if "error" in result else 200)
        except (TypeError, ValueError):
            return JSONResponse(
                {
                    "error": {
                        "code": "invalid_request",
                        "message": "invalid JSON request",
                    }
                },
                status_code=400,
            )

    app.routes.append(Route("/v1/{name}", operation, methods=["POST"]))

    class BearerMiddleware(BaseHTTPMiddleware):
        async def dispatch(self, request: Request, call_next: Callable):
            supplied = request.headers.get("authorization", "")
            if not hmac.compare_digest(supplied, f"Bearer {token}"):
                return JSONResponse({"error": "unauthorized"}, status_code=401)
            if request.method == "POST":
                size = request.headers.get("content-length")
                if size is not None and not size.isdecimal():
                    return JSONResponse(
                        {"error": "invalid content length"}, status_code=400
                    )
                if size is not None and int(size) > 4_194_304:
                    return JSONResponse({"error": "request too large"}, status_code=413)
                if len(await request.body()) > 4_194_304:
                    return JSONResponse({"error": "request too large"}, status_code=413)
            return await call_next(request)

    app.add_middleware(BearerMiddleware)
    return app

"""Versioned records shared by local and future remote backends."""

from __future__ import annotations

import unicodedata
from dataclasses import asdict, dataclass, field
from typing import Any, Literal


@dataclass(frozen=True, slots=True)
class Principal:
    tenant_id: str
    user_id: str
    version: int = 1

    def __post_init__(self) -> None:
        for name in ("tenant_id", "user_id"):
            value = unicodedata.normalize("NFC", getattr(self, name))
            if (
                not value
                or value in {".", ".."}
                or any(c in value for c in "/\\%?#\x00")
                or any(ord(c) < 32 or ord(c) == 127 for c in value)
            ):
                raise ValueError("principal needs safe tenant and user identifiers")
            object.__setattr__(self, name, value)

    def to_dict(self) -> dict[str, Any]:
        return asdict(self)


@dataclass(frozen=True, slots=True)
class TenantScope:
    tenant_id: str
    version: int = 1

    def to_dict(self) -> dict[str, Any]:
        return asdict(self)


@dataclass(frozen=True, slots=True)
class PackageRef:
    sha256: str
    size_bytes: int
    version: int = 1


@dataclass(frozen=True, slots=True)
class NodeAddress:
    document_id: str
    revision_id: str
    xpath: str
    version: int = 1


@dataclass(frozen=True, slots=True)
class DocumentRecord:
    uri: str
    tenant_id: str
    document_id: str
    revision_id: str
    package: PackageRef
    parent_uri: str | None
    source: dict[str, Any] = field(default_factory=dict)
    created_at: str = ""
    updated_at: str = ""
    version: int = 1

    def to_dict(self) -> dict[str, Any]:
        return asdict(self)


@dataclass(frozen=True, slots=True)
class TreeEntry:
    uri: str
    kind: Literal["directory", "document"]
    depth: int
    document_id: str | None = None
    revision_id: str | None = None
    version: int = 1


@dataclass(frozen=True, slots=True)
class ChangeEvent:
    sequence: int
    tenant_id: str
    uri: str
    document_id: str
    revision_id: str
    operation: Literal["put", "delete"]
    occurred_at: str
    version: int = 1

    def to_dict(self) -> dict[str, Any]:
        return asdict(self)


@dataclass(frozen=True, slots=True)
class NodeContent:
    address: NodeAddress
    text: str
    truncated: bool
    page: int | None
    bbox: tuple[tuple[float, float], tuple[float, float]] | None
    version: int = 1

"""Direct text, image, and mixed-input embedding behavior."""

from __future__ import annotations

import sys
from types import ModuleType, SimpleNamespace

import pytest

from docling_context import (
    CLIP_MODEL,
    DEFAULT_MODEL,
    FastEmbedProvider,
    embed_image,
    embed_text,
    embed_text_image,
    embeddings,
)


class TextOnly:
    model_id = "fixture"
    dimensions = 8

    def embed(self, texts: list[str]) -> list[list[float]]:
        return [[float(len(text)), *([0.0] * 7)] for text in texts]


def test_text_only_provider_skips_unsupported_images():
    provider = TextOnly()
    assert embed_text(provider, "rock") == [4.0, *([0.0] * 7)]
    assert embed_image(provider, b"image") is None
    assert embed_text_image(provider, "rock", b"image") == embed_text(provider, "rock")
    assert embed_text_image(provider, "", b"image") is None


def test_fastembed_provider_keeps_query_and_passage_paths_separate(monkeypatch):
    class FakeVector(list):
        def tolist(self):
            return list(self)

    class FakeTextEmbedding:
        @staticmethod
        def list_supported_models():
            return [
                {"model": DEFAULT_MODEL},
                {"model": "Qdrant/clip-ViT-B-32-text"},
            ]

        @staticmethod
        def get_embedding_size(_model):
            return 8

        def __init__(self, **_kwargs):
            pass

        def passage_embed(self, texts):
            return iter(FakeVector([1.0, *([0.0] * 7)]) for _ in texts)

        def query_embed(self, _text):
            return iter([FakeVector([0.0, 1.0, *([0.0] * 6)])])

    class FakeImageEmbedding:
        def __init__(self, **_kwargs):
            pass

        def embed(self, paths):
            assert list(paths)
            return iter([FakeVector([0.0, 1.0, *([0.0] * 6)])])

    monkeypatch.setitem(
        sys.modules,
        "fastembed",
        SimpleNamespace(
            TextEmbedding=FakeTextEmbedding, ImageEmbedding=FakeImageEmbedding
        ),
    )
    text_provider = FastEmbedProvider()
    assert text_provider.embed_text("rock")[0] == 1.0
    assert text_provider.embed_query("rock")[1] == 1.0
    assert text_provider.embed_image(b"image") is None
    assert text_provider.embed_text_image("rock", b"image") == text_provider.embed_text(
        "rock"
    )
    assert text_provider.embed_text_image("", b"image") is None
    mixed = FastEmbedProvider(CLIP_MODEL)
    assert mixed.embed_image(b"image")[1] == 1.0
    vector = mixed.embed_text_image("rock", b"image")
    assert vector is not None and vector[0] > 0 and vector[1] > 0


def test_mlx_auto_selection_and_saved_backend_identity(monkeypatch):
    encoded: list[list[str]] = []

    class FakeResult:
        def __init__(self, texts):
            self.texts = texts

        def tolist(self):
            return [[1.0, *([0.0] * 383)] for _ in self.texts]

    class FakeModel:
        @classmethod
        def from_registry(cls, name):
            assert name == "bge-small"
            return cls()

        def encode(self, texts, *, show_progress):
            assert show_progress is False
            encoded.append(texts)
            return FakeResult(texts)

    package = ModuleType("mlx_embedding_models")
    package.__path__ = []
    embedding_module = ModuleType("mlx_embedding_models.embedding")
    embedding_module.EmbeddingModel = FakeModel
    registry_module = ModuleType("mlx_embedding_models.registry")
    registry_module.registry = {"bge-small": {"ndim": 384}}
    monkeypatch.setitem(sys.modules, "mlx_embedding_models", package)
    monkeypatch.setitem(sys.modules, "mlx_embedding_models.embedding", embedding_module)
    monkeypatch.setitem(sys.modules, "mlx_embedding_models.registry", registry_module)
    monkeypatch.setattr(embeddings, "_apple_silicon", lambda: True)
    monkeypatch.setattr(embeddings, "find_spec", lambda _name: object())

    class FakeOnnx:
        def __init__(self, model_name, *, offline=False):
            self.model_id = model_name
            self.offline = offline

    monkeypatch.setattr(embeddings, "FastEmbedProvider", FakeOnnx)
    provider = embeddings.local_embedding_provider(DEFAULT_MODEL)
    assert provider.model_id == "mlx:BAAI/bge-small-en-v1.5"
    assert provider.dimensions == 384
    assert provider.embed(["rock"])[0][0] == 1.0
    provider.embed_query("rock")
    assert encoded[-1][0].startswith("Represent this sentence")
    assert (
        embeddings.stored_embedding_provider(provider.model_id).model_id
        == provider.model_id
    )
    assert embeddings.stored_embedding_provider(DEFAULT_MODEL).model_id == DEFAULT_MODEL
    assert embeddings.local_embedding_provider(CLIP_MODEL).model_id == CLIP_MODEL
    assert embeddings.local_embedding_provider(DEFAULT_MODEL, offline=True).offline
    monkeypatch.setattr(embeddings, "find_spec", lambda _name: None)
    assert embeddings.local_embedding_provider(DEFAULT_MODEL).model_id == DEFAULT_MODEL
    with pytest.raises(ValueError, match="does not support"):
        embeddings.local_embedding_provider(CLIP_MODEL, backend="mlx")
